@pytest.mark.parametrize(
    'seed,i,j,fibre_cells,expected',
    material
)
def test_link_map(seed, i, j, fibre_cells, expected):
    """
    Regression test from visually inspected outputs.
    """
    env, _, _ = env_generator(seed=seed)
    stations_links = env.stations_links
    print(stations_links)

    link = stations_links.links[i]
    fibre = link.fibres[j]
    actual = extract_link_map(stations_links, link, Fibre(edges=fibre_cells, from_pin=fibre.from_pin, to_pin=fibre.to_pin), env.rail)
    assert set(actual.keys()) == set(expected.keys())
    for k in actual.keys():
        if k == 'grid':
            pass
            diff = np.argwhere(actual[k] != expected[k])
            print(diff)
            for rc in diff:
                try:
                    print(f"diff at {diff}: actual {RailEnvTransitionsEnum(actual[k][*rc]).name}, expected: {RailEnvTransitionsEnum(expected[k][*rc]).name}")
                except ValueError:
                    print(f"diff at {diff}: actual {actual[k][*rc]}, expected: {RailEnvTransitionsEnum(expected[k][*rc]).name}")
            assert np.array_equal(actual[k], expected[k])
        elif k == 'mapping':
            act = {ke: v for pairs in actual[k] for ke, v in pairs}
            exp = {ke: v for pairs in expected[k] for ke, v in pairs}
            assert act == exp
        else:
            assert actual[k] == expected[k], k


